// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address to, uint256 v) public {
        vm.assume(to != address(0));
        address[] memory tos = new address[](1);
        tos[0] = to;
        bool ok;
        // low-level call to any address succeeds (EOA has no code), so transfer completes
        // and its boolean return value is observable at the boundary
        (bool success, bytes memory ret) = address(c).call(
            abi.encodeWithSelector(c.transfer.selector, from, caddress, tos, v)
        );
        ok = success && abi.decode(ret, (bool));
        assertTrue(ok);
    }
}
